{
  "properties": {
    "hs_note_body": "[RECURRING] Monthly payment logged: ${{2.amount}} {{2.currency}} on {{2.payment_date}}. Description: {{2.description}}. Customer: {{2.customer_email}}",
    "hs_timestamp": "{{formatDate(now; 'X') * 1000}}"
  },
  "associations": [
    {
      "to": {
        "id": "{{3.body.results[0].id}}"
      },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 279
        }
      ]
    }
  ]
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Make.com — Scenario F Payment Logging Failed",
  "html": "<h2>Payment Logging Error — Scenario F</h2><p>A payment event failed to process. Please review and manually log this payment in HubSpot.</p><hr><h3>Payment Details</h3><ul><li><strong>Amount:</strong> ${{2.amount}} {{2.currency}}</li><li><strong>Customer Email:</strong> {{2.customer_email}}</li><li><strong>Payment Date:</strong> {{2.payment_date}}</li><li><strong>Description:</strong> {{2.description}}</li><li><strong>Stripe Payment Intent ID:</strong> {{1.data.id}}</li><li><strong>Stripe Customer ID:</strong> {{1.data.customer}}</li><li><strong>Stripe Status:</strong> {{1.data.status}}</li></ul><hr><h3>Error Details</h3><ul><li><strong>Error Message:</strong> {{error.message}}</li><li><strong>Failed Module:</strong> {{error.module}}</li><li><strong>Scenario Run ID:</strong> {{scenario.runId}}</li><li><strong>Timestamp:</strong> {{formatDate(now; 'YYYY-MM-DD HH:mm:ss'; 'America/New_York')}} ET</li></ul><hr><p><em>This is an automated alert from Make.com CWI Automation — Scenario F: Payment Logging.</em></p>"
}
